        if (counter == LOCK_TIME) begin
            locked_reg <= 1;
        end

        // Increment counters
        counter <= counter + 1;
        if (feedback_divider == FEEDBACK_DIVIDER) begin
            feedback_divider <= 0;
            if (refclk_divider == REFCLK_DIVIDER) begin
                refclk_divider <= 0;
                outclk <= ~outclk;
            end else begin
                refclk_divider <= refclk_divider + 1;
            end
        end else begin
            feedback_divider <= feedback_divider + 1;
        end
    end
end

always @(posedge refclk) begin
