          if (in == I0) begin
            state <= S2;
            out <= O0;
          end else if (in == I1) begin
            state <= S3;
            out <= O1;
          end else begin
            state <= S1;
            out <= O0;
          end
        end
        S2: begin
          if (in == I0) begin
            state <= S3;
            out <= O0;
          end else if (in == I1) begin
            state <= S0;
            out <= O1;
          end else begin
            state <= S2;
            out <= O0;
