          if (in == I0) begin
            state <= S0;
            out <= O0;
          end else if (in == I1) begin
            state <= S1;
            out <= O1;
          end else begin
            state <= S3;
            out <= O0;
          end
        end
      endcase
    end
  end

  initial begin
    state <= S0;
  end

