module clk_divider (
  input CLK_IN1,
  input COUNTER_RESET,
  input RESET,
  output reg CLK_OUT,
  output reg LOCKED
);

  // Parameters for the counters
  localparam C_W = 16;

  // Counter for dividing the clock
  reg [C_W-1:0] counter;

  // Divided clock output
  always @(posedge CLK_IN1 or posedge RESET) begin
    if (RESET) begin
      CLK_OUT <= 1'b0;
    end else begin
      CLK_OUT <= counter[C_W-1];
    end
