  always @(posedge CLK_IN1 or posedge COUNTER_RESET) begin
    if (COUNTER_RESET) begin
      counter <= #1 { C_W { 1'b0 } };
    end else begin
      counter <= #1 counter + 1'b1;
    end
  end

  // Locked output
  always @(posedge CLK_IN1) begin
    if (CLK_OUT == 1'b0 && !RESET) begin
      LOCKED <= 1'b1;
    end else begin
      LOCKED <= 1'b0;
    end
  end

  // High bit output
  reg [0:0] COUNT;
  always @* begin
    COUNT = counter[C_W-1];
  end

